using System.ComponentModel.DataAnnotations;

namespace sv_d508fe8577e345d5aa68c5e68184879c.Models;

public class RegistrationModel
{
    [Required(ErrorMessage = "Name is required.")]
    [Display(Name = "Attendee Name")]
    public string Name { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
    public string Email { get; set; } = string.Empty;

    [Range(0, 5, ErrorMessage = "Number of guests must be between 0 and 5.")]
    [Display(Name = "Number of Guests")]
    public int NumberOfGuests { get; set; }

    [Required]
    [Display(Name = "Preferred Session")]
    public SessionTime PreferredSession { get; set; } = SessionTime.Morning;

    [Display(Name = "Special Dietary Requirements")]
    public string? DietaryRequirements { get; set; }
}

public enum SessionTime
{
    Morning,
    Afternoon,
    Evening
}

using sv_d508fe8577e345d5aa68c5e68184879c.Models;

namespace sv_d508fe8577e345d5aa68c5e68184879c.Services;

public class RegistrationService
{
    /// <summary>
    /// Validates the registration on the server side.
    /// Returns a dictionary of field-specific errors (field name → error message).
    /// An empty dictionary means validation passed.
    /// </summary>
    public Task<Dictionary<string, string>> ValidateAsync(RegistrationModel model)
    {
        var errors = new Dictionary<string, string>();

        if (string.Equals(model.Email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(model.Email)] = "This email is already registered.";
        }

        return Task.FromResult(errors);
    }
}

@page "/register"
@rendermode InteractiveServer
@using sv_d508fe8577e345d5aa68c5e68184879c.Models
@using sv_d508fe8577e345d5aa68c5e68184879c.Services
@inject RegistrationService RegistrationService

<PageTitle>Event Registration</PageTitle>

<h3>Event Registration</h3>

@if (isRegistered)
{
    <div class="alert alert-success mt-3">
        <strong>Registration successful!</strong> Thank you, @Model.Name.
    </div>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="register" class="mt-3" style="max-width: 500px;">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label class="form-label" for="name">Attendee Name</label>
            <InputText id="name" class="form-control" @bind-Value="Model.Name" />
            <ValidationMessage For="() => Model.Name" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="guests">Number of Guests</label>
            <InputNumber id="guests" class="form-control" @bind-Value="Model.NumberOfGuests" />
            <ValidationMessage For="() => Model.NumberOfGuests" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="session">Preferred Session</label>
            <InputSelect id="session" class="form-select" @bind-Value="Model.PreferredSession">
                @foreach (var session in Enum.GetValues<SessionTime>())
                {
                    <option value="@session">@session</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.PreferredSession" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="dietary">Special Dietary Requirements</label>
            <InputTextArea id="dietary" class="form-control" @bind-Value="Model.DietaryRequirements" />
        </div>

        <button type="submit" class="btn btn-primary" disabled="@isSubmitting">
            @if (isSubmitting)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Register
        </button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private RegistrationModel Model { get; set; } = new();

    private bool isSubmitting;
    private bool isRegistered;

    private async Task HandleSubmit()
    {
        isSubmitting = true;

        try
        {
            var serverErrors = await RegistrationService.ValidateAsync(Model);

            if (serverErrors.Count > 0)
            {
                var messageStore = new ValidationMessageStore(editContext!);
                foreach (var (field, message) in serverErrors)
                {
                    messageStore.Add(editContext!.Field(field), message);
                }
                editContext!.NotifyValidationStateChanged();
                return;
            }

            isRegistered = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private EditContext? editContext;

    protected override void OnInitialized()
    {
        editContext = new EditContext(Model);
    }
}

