private RegistrationModel Model { get; set; } = new();

private EditContext editContext = default!;
private ValidationMessageStore serverMessageStore = default!;
private bool isSubmitting;
private bool isRegistered;

protected override void OnInitialized()
{
    editContext = new EditContext(Model);
    serverMessageStore = new ValidationMessageStore(editContext);

    // Clear server errors when the user modifies a field
    editContext.OnFieldChanged += (_, args) =>
    {
        serverMessageStore.Clear(args.FieldIdentifier);
        editContext.NotifyValidationStateChanged();
    };
}

private async Task HandleSubmit()
{
    isSubmitting = true;

    try
    {
        serverMessageStore.Clear();
        var serverErrors = await RegistrationService.ValidateAsync(Model);

        if (serverErrors.Count > 0)
        {
            foreach (var (field, message) in serverErrors)
            {
                serverMessageStore.Add(editContext.Field(field), message);
            }
            editContext.NotifyValidationStateChanged();
            return;
        }

        isRegistered = true;
    }
    finally
    {
        isSubmitting = false;
    }
}

